package com.example.customers.domain;

/**
 * A customer record. Immutable; loaded from {@code customers.csv} at startup.
 */
public record Customer(
        long id,
        String firstName,
        String lastName,
        String email,
        String country,
        CustomerStatus status) {

    public String fullName() {
        return firstName + " " + lastName;
    }
