import java.util.Set;

import org.junit.jupiter.api.Test;

class CustomerFilterTest {

    private static final Customer ADA = new Customer(1, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
    private static final Customer JOSEPHINE = new Customer(2, "Joséphine", "Engberg", "j@example.com", "Denmark", CustomerStatus.PENDING);
    private static final Customer MAKINEN_ACCENTED = new Customer(3, "Jarno", "Mäkinen", "m@example.com", "Estonia", CustomerStatus.CLOSED);
    private static final Customer MAKINEN_PLAIN = new Customer(4, "Maria", "Makinen", "p@example.com", "Spain", CustomerStatus.ACTIVE);

    @Test
    void theEmptyFilterMatchesEveryone() {
        assertTrue(matches(CustomerFilter.ALL, ADA));
        assertTrue(matches(CustomerFilter.ALL, MAKINEN_ACCENTED));
    }

    @Test
    void everyTermMustAppearInFirstOrLastName() {
        assertTrue(matches("ada aal", ADA));
        assertTrue(matches("aal ada", ADA));
        assertTrue(matches("ada ada", ADA));
        assertFalse(matches("ada virtanen", ADA));
    }

    @Test
    void whitespaceIsNotSignificant() {
        assertTrue(matches("  ada   aal\t", ADA));
        assertTrue(matches(" ada aal", ADA));
        assertTrue(matches("   ", ADA));
    }

    @Test
    void caseIsIgnored() {
        assertTrue(matches("ADA", ADA));
        assertTrue(matches("aALtOnEn", ADA));
    }

    @Test
    void accentsAreIgnoredInBothDirections() {
        assertTrue(matches("makinen", MAKINEN_ACCENTED));
        assertTrue(matches("MAKINEN", MAKINEN_ACCENTED));
        assertTrue(matches("mäkinen", MAKINEN_ACCENTED));
        assertTrue(matches("mäkinen", MAKINEN_PLAIN));
        assertTrue(matches("josephine", JOSEPHINE));
        assertTrue(matches("JOSÉPHINE", JOSEPHINE));
    }

    @Test
    void aStatusFilterKeepsOnlyTheSelectedStatuses() {
        assertTrue(matches(new CustomerFilter("", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED)), ADA));
        assertFalse(matches(new CustomerFilter("", Set.of(CustomerStatus.PENDING)), ADA));
    }

    @Test
    void theNameAndTheStatusMustBothMatch() {
        CustomerFilter activeAda = new CustomerFilter("ada", Set.of(CustomerStatus.ACTIVE));
        CustomerFilter pendingAda = new CustomerFilter("ada", Set.of(CustomerStatus.PENDING));

        assertTrue(matches(activeAda, ADA));
        assertFalse(matches(pendingAda, ADA));
    }

    private static boolean matches(String name, Customer customer) {
        return matches(new CustomerFilter(name, Set.of()), customer);
    }

    private static boolean matches(CustomerFilter filter, Customer customer) {
        return filter.toPredicate().test(customer);
    }
}
