    private static void updateAddressBar(CustomerFilter filter) {
        List<String> parameters = new ArrayList<>();
        if (!filter.name().isBlank()) {
            parameters.add("name=" + URLEncoder.encode(filter.name(), StandardCharsets.UTF_8).replace("+", "%20"));
        }
        if (!filter.statuses().isEmpty()) {
            parameters.add("status=" + filter.statuses().stream()
                    .sorted()
                    .map(CustomerStatus::name)
                    .collect(Collectors.joining(",")));
        }
        String url = parameters.isEmpty() ? "./" : "?" + String.join("&", parameters);
        UI.getCurrent().getPage().executeJs("window.history.replaceState(null, '', $0)", url);
    }

