        List<String> names = Arrays.stream(commaSeparated.split(",")).map(String::strip).toList();
        return Arrays.stream(CustomerStatus.values())
                .filter(status -> names.contains(status.name()))
                .collect(Collectors.toSet());
    }

    private static List<CustomerSort> toSorts(List<QuerySortOrder> sortOrders) {
        return sortOrders.stream()
                .map(order -> new CustomerSort(
                        order.getSorted(), order.getDirection() == SortDirection.ASCENDING))
                .toList();
    }
