package com.example.customers;

import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.regex.Pattern;

import com.example.customers.domain.QueryLog;
import com.microsoft.playwright.Locator;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
import org.vaadin.addons.dramafinder.element.MultiSelectComboBoxElement;

/**
 * Drives the customer list in a real browser, to check what the address bar shows
 * and what typing costs the backend. The browserless {@link CustomerListViewTest}
 * covers the rest.
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class CustomerListBrowserTest extends AbstractBasePlaywrightIT {

    @LocalServerPort
    private int port;

    @Autowired
    private QueryLog queryLog;

    @Override
    public String getUrl() {
        return "http://localhost:" + port + "/";
    }

    @Test
    void aFilteredAddressOpensWithTheFilterInTheFields() {
        page.navigate(getUrl() + "?name=vir&status=ACTIVE,CLOSED");

        assertThat(nameFilter()).hasValue("vir");
        MultiSelectComboBoxElement.getByLabel(page, "Status").assertSelectedItems("ACTIVE", "CLOSED");
        assertThat(page.getByText("Showing 10 of 500")).isVisible();
        assertThat(page).hasURL(exactly(getUrl() + "?name=vir&status=ACTIVE,CLOSED"));
    }

    @Test
    void typingNarrowsTheListWithoutAddingHistoryOrQueryingPerKeystroke() {
        page.navigate(getUrl());
        assertThat(page.getByText("Showing 500 of 500")).isVisible();
        int historyLength = (Integer) page.evaluate("window.history.length");
        int queriesBefore = queryCount();

        nameFilter().pressSequentially("makinen");

        assertThat(page.getByText("Showing 15 of 500")).isVisible();
        assertThat(page).hasURL(exactly(getUrl() + "?name=makinen"));
        assertEquals(historyLength, (Integer) page.evaluate("window.history.length"),
                "Changing the filter must replace the address, not add history entries");
        int cost = queryCount() - queriesBefore;
        assertTrue(cost <= 2, "Typing 7 characters cost " + cost + " queries: pages "
                + queryLog.pageQueries() + ", counts " + queryLog.countQueries());
    }

    @Test
    void theAddressBarFollowsBothFiltersAndDropsThemWhenCleared() {
        page.navigate(getUrl());

        nameFilter().fill("ada aal");
        assertThat(page.getByText("Showing 2 of 500")).isVisible();
        assertThat(page).hasURL(exactly(getUrl() + "?name=ada%20aal"));

        MultiSelectComboBoxElement statuses = MultiSelectComboBoxElement.getByLabel(page, "Status");
        statuses.selectItem("ACTIVE");
        assertThat(page).hasURL(exactly(getUrl() + "?name=ada%20aal&status=ACTIVE"));

        nameFilter().fill("");
        statuses.deselectItem("ACTIVE");
        assertThat(page.getByText("Showing 500 of 500")).isVisible();
        assertThat(page).hasURL(exactly(getUrl()));
    }

    /** The input inside the name filter; Playwright's placeholder lookup also matches the host element. */
    private Locator nameFilter() {
        return page.locator("input[placeholder='Filter by name']");
    }

    private int queryCount() {
        return queryLog.pageQueries().size() + queryLog.countQueries().size();
    }

    /** A pattern matching exactly this URL. Escaped for JavaScript, which Playwright evaluates it with, so not {@link Pattern#quote}. */
    private static Pattern exactly(String url) {
        return Pattern.compile("^" + url.replaceAll("[.?+*()\\[\\]{}|^$\\\\]", "\\\\$0") + "$");
    }
}

