+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * Which customers a query returns. A customer is kept only if it satisfies both
+ * parts.
+ *
+ * @param name     text typed into the name filter. It is split on whitespace into
+ *                 terms, and every term must appear in the first or the last name.
+ *                 Case and accents are ignored. Blank matches every name.
+ * @param statuses the statuses to keep; empty keeps every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter ALL = new CustomerFilter("", Set.of());
+
+    private static final Pattern WORD_SEPARATOR = Pattern.compile("[\\s\\p{Z}]+");
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        statuses = Set.copyOf(statuses);
+    }
+
+    /**
+     * Returns a test for this filter. The name is folded and split here, once,
+     * rather than again for every customer.
+     */
+    public Predicate<Customer> toPredicate() {
+        List<String> terms = WORD_SEPARATOR.splitAsStream(fold(name))
+                .filter(term -> !term.isEmpty())
+                .toList();
+        return customer -> (statuses.isEmpty() || statuses.contains(customer.status()))
+                && matchesEveryTerm(terms, customer);
+    }
+
+    private static boolean matchesEveryTerm(List<String> terms, Customer customer) {
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    /** Strips accents and lower-cases, so {@code Mäkinen}, {@code MAKINEN} and {@code makinen} compare equal. */
+    private static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
