+        _setValue(name, "aal");
+
+        assertEquals(List.of(15), queryLog.countQueries(),
+                "A filter change must ask the backend for one count, and show what it says");
+    }
+
+    @Test
+    void aFilterChangeCostsOneCountAndOnePageQuery() {
+        Grid<?> grid = grid();
+        TextField name = _get(TextField.class);
+        queryLog.clear();
+
+        _setValue(name, "mäkinen");
+        _getFormattedRow(grid, 0);
+
+        int queries = queryLog.countQueries().size() + queryLog.pageQueries().size();
+        assertTrue(queries <= 2, "One filter change cost " + queries + " queries: " + queryLog.pageQueries()
+                + " pages and " + queryLog.countQueries() + " counts");
+    }
+
+    @Test
+    void sortingWorksWhileAFilterIsApplied() {
+        _setValue(_get(TextField.class), "ada");
+        Grid<?> grid = grid();
+        assertEquals(13, _size(grid));
+
+        _sortByKey(grid, "lastName", SortDirection.DESCENDING);
+
+        List<String> lastNames = new ArrayList<>();
+        for (int i = 0; i < _size(grid); i++) {
+            lastNames.add(_getFormattedRow(grid, i).get(1));
+        }
+        List<String> expected = new ArrayList<>(lastNames);
+        expected.sort(String.CASE_INSENSITIVE_ORDER.reversed());
+        assertEquals(expected, lastNames);
+    }
+
+    @Test
+    void openingTheViewWithAFilterInTheAddressBarAppliesIt() {
+        UI.getCurrent().navigate("", QueryParameters.fromString("name=vir&status=ACTIVE,CLOSED"));
+
+        assertEquals("vir", _get(TextField.class).getValue());
+        assertEquals(Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED),
+                _get(MultiSelectComboBox.class).getValue());
+        assertEquals("Showing 10 of 500", summary());
+        assertEquals(10, _size(grid()));
+    }
+
+    private static Grid<?> grid() {
+        return _get(Grid.class);
+    }
+
+    /** The text of the summary line above the grid. */
+    private static String summary() {
+        return _find(Span.class).stream()
+                .map(Span::getText)
+                .filter(text -> text.startsWith("Showing "))
+                .findFirst()
+                .orElseThrow();
+    }
+
+    /** The "First Last" name of every row the grid shows. */
+    private static List<String> shownNames(Grid<?> grid) {
+        List<String> names = new ArrayList<>();
+        for (int i = 0; i < _size(grid); i++) {
+            List<String> row = _getFormattedRow(grid, i);
+            names.add(row.get(0) + " " + row.get(1));
+        }
+        return names;
+    }
 }
diff --git a/src/test/java/com/example/customers/domain/CustomerFilterTest.java b/src/test/java/com/example/customers/domain/CustomerFilterTest.java
